package com.qrcodegen.core.simbologias

/**
 * A tabela de Application Identifiers do GS1. Gerado por
 * ``spec/gerar-tabelas-gs1.py` a partir do JSON-LD de ref.gs1.org.
 * * Sao 541 AIs e nao estao escritos a mao de proposito: mais de quinhentos AIs
 * nao se escrevem de memoria, e um AI com o comprimento errado da um codigo que
 * se desenha certo e que o leitor le como invalido.
 * * A origem e' https://ref.gs1.org/ai/?lang=en.
 */
object TabelasGs1 {

    /**
     * Um componente de um AI: o tipo, e o comprimento como par fixo/maximo.
     *
     * **Um dos dois e' sempre nulo**, e e' assim que se distingue um campo de
     * comprimento fixo de um variavel sem um booleano a mais. **Um campo que
     * aceite os dois nao se sabe ler** — o AI `3103` e' um campo fixo de tres
     * digitos mais um campo variavel, e nao um campo fixo de quatro.
     */
    data class Componente(val tipo: String, val fixo: Int?, val maximo: Int?)

    /**
     * Um AI, com tudo o que o encoder precisa dele.
     *
     * `separador` diz se o campo precisa de um FNC1 a separa-lo do seguinte.
     * **E' a razao de existir esta tabela**: sem ela nao se sabe onde acaba
     * `(10)LOTE-A1` e onde comeca o campo seguinte.
     *
     * **`resto` so' existe na procura**: um AI procurado directamente tem
     * `resto` nulo, e e' por isso que nao ha um campo separado para o
     * numero procurado.
     */
    data class Ai(
        val numero: String,
        val formato: String,
        val fixo: Int?,
        val maximo: Int?,
        val campos: List<Componente>,
        val separador: Boolean,
        val regex: String,
        val resto: String?,
    ) {
        /** O mesmo AI, com o numero procurado e o que sobrou do campo. */
        fun buscado(numeroEfectivo: String, restoEfectivo: String?): Ai =
            Ai(numeroEfectivo, formato, fixo, maximo, campos, separador, regex,
                restoEfectivo)
    }

